  lang: "c",
  code: `#include <stdio.h>
#include <string.h>

#define NAME_LEN 50
#define PROG_LEN 50
#define MAX_STUDENTS 60

struct Student {
    int sid;
    char name[NAME_LEN];
    char prog[PROG_LEN];
    int s1, s2, s3;
};

