            clear_stdin();
            printf("Please enter a valid integer for Student ID: ");
        }
        clear_stdin();

        printf("Name: ");
        if (!fgets(s[i].name, sizeof s[i].name, stdin)) s[i].name[0] = '\\0';
        s[i].name[strcspn(s[i].name, "\\n")] = '\\0';

        printf("Course: ");
        if (!fgets(s[i].prog, sizeof s[i].prog, stdin)) s[i].prog[0] = '\\0';
        s[i].prog[strcspn(s[i].prog, "\\n")] = '\\0';

        printf("C Programming Marks: ");
        while (scanf("%d", &s[i].s1) != 1) {
            clear_stdin();
            printf("Enter integer marks: ");
        }

        printf("DBMS Marks: ");
        while (scanf("%d", &s[i].s2) != 1) {
            clear_stdin();
            printf("Enter integer marks: ");
        }

        printf("Discrete Maths Marks: ");
        while (scanf("%d", &s[i].s3) != 1) {
            clear_stdin();
            printf("Enter integer marks: ");
        }
        clear_stdin();
    }

    printf("\\nI BCA - A\\n");
    printf("------------------------------------------------------------\\n");
    printf("RegNo   Name                     C-Prog  DBMS   DM     Total  %%\\n");
    printf("------------------------------------------------------------\\n");

    for (i = 0; i < n; i++) {
        int total = s[i].s1 + s[i].s2 + s[i].s3;
        double per = total / 3.0;
        printf("%-7d %-24s %-7d %-6d %-6d %-6d %.2f\\n",
               s[i].sid, s[i].name, s[i].s1, s[i].s2, s[i].s3, total, per);
    }

    printf("------------------------------------------------------------\\n");
    return 0;
}
`
};
